// Viterbi smoothing of the correlation lattice: finds the residual-delay
// path that maximizes correlation subject to a hard slope constraint (max
// drift rate) and a quadratic slope penalty. Gated rows contribute a flat
// observation so the path coasts through silence on the transition prior.

const AGILITY = {
  low: { slopeLimit: 8 },
  medium: { slopeLimit: 24 },
  high: { slopeLimit: 48 },
};

/**
 * @param {{ rows, L }} lattice from buildLattice
 * @param {object} opts { slopeLimit (samples/hop), lambda }
 * @returns {{ lags: Float64Array, gatedMask: Uint8Array }} sub-sample residual
 *   lag per row (samples, relative to d0Int)
 */
function solvePath(lattice, opts = {}) {
  const { rows, L } = lattice;
  const nLags = 2 * L + 1;
  const T = rows.length;
  const { slopeLimit = 24, lambda = 1 / (2 * slopeLimit * slopeLimit) } = opts;
  if (T === 0) return { lags: new Float64Array(0), gatedMask: new Uint8Array(0) };

  const obs = (row, j) => (row.gated ? 0 : 1 - row.corr[j]);

  let prev = new Float64Array(nLags);
  let cur = new Float64Array(nLags);
  const backptr = new Int32Array(T * nLags);
  for (let j = 0; j < nLags; j++) prev[j] = obs(rows[0], j);

  // precompute transition penalties for each delta
  const penalties = new Float64Array(2 * slopeLimit + 1);
  for (let d = -slopeLimit; d <= slopeLimit; d++) {
    penalties[d + slopeLimit] = lambda * d * d;
  }

  for (let t = 1; t < T; t++) {
    const row = rows[t];
    const base = t * nLags;
    for (let j = 0; j < nLags; j++) {
      let best = Infinity;
      let bestFrom = j;
      const lo = Math.max(0, j - slopeLimit);
      const hi = Math.min(nLags - 1, j + slopeLimit);
      for (let k = lo; k <= hi; k++) {
        const c = prev[k] + penalties[j - k + slopeLimit];
        if (c < best) {
          best = c;
          bestFrom = k;
        }
      }
      cur[j] = best + obs(row, j);
      backptr[base + j] = bestFrom;
    }
    const tmp = prev;
    prev = cur;
    cur = tmp;
  }

  // backtrack
  let endJ = 0;
  let endCost = Infinity;
  for (let j = 0; j < nLags; j++) {
    if (prev[j] < endCost) {
      endCost = prev[j];
      endJ = j;
    }
  }
  const pathIdx = new Int32Array(T);
  pathIdx[T - 1] = endJ;
  for (let t = T - 1; t > 0; t--) {
    pathIdx[t - 1] = backptr[t * nLags + pathIdx[t]];
  }

  // sub-sample refinement on ungated rows via parabolic interpolation
  const lags = new Float64Array(T);
  const gatedMask = new Uint8Array(T);
  for (let t = 0; t < T; t++) {
    const j = pathIdx[t];
    let lag = j - L;
    const row = rows[t];
    gatedMask[t] = row.gated ? 1 : 0;
    if (!row.gated && j > 0 && j < nLags - 1) {
      const y0 = row.corr[j - 1];
      const y1 = row.corr[j];
      const y2 = row.corr[j + 1];
      const denom = y0 - 2 * y1 + y2;
      if (Math.abs(denom) > 1e-20) {
        const frac = (0.5 * (y0 - y2)) / denom;
        if (frac > -1 && frac < 1) lag += frac;
      }
    }
    lags[t] = lag;
  }
  return { lags, gatedMask };
}

/**
 * Expand per-window residual lags into a smooth per-sample delay curve.
 * Linear interpolation between window centers followed by a two-pass moving
 * average; flat extrapolation beyond the first/last center.
 * @returns {Float64Array} length outLen, in samples (residual only)
 */
function expandPath(lattice, lags, outLen, { smoothPasses = 2 } = {}) {
  const { rows, hop } = lattice;
  const T = rows.length;
  const curve = new Float64Array(outLen);
  if (T === 0) return curve;
  if (T === 1) {
    curve.fill(lags[0]);
    return curve;
  }
  let seg = 0;
  for (let n = 0; n < outLen; n++) {
    while (seg < T - 2 && n > rows[seg + 1].center) seg++;
    const c0 = rows[seg].center;
    const c1 = rows[seg + 1].center;
    let v;
    if (n <= c0) v = lags[seg];
    else if (n >= c1) v = lags[seg + 1];
    else v = lags[seg] + ((lags[seg + 1] - lags[seg]) * (n - c0)) / (c1 - c0);
    curve[n] = v;
  }
  // moving-average smoothing (box of one hop) to soften slope discontinuities
  const w = Math.max(2, hop);
  for (let pass = 0; pass < smoothPasses; pass++) {
    let acc = 0;
    const out = new Float64Array(outLen);
    for (let n = 0; n < outLen; n++) {
      acc += curve[n];
      if (n >= w) acc -= curve[n - w];
      out[n] = acc / Math.min(n + 1, w);
    }
    // the causal box introduces w/2 latency; shift back by half the window
    const half = w >> 1;
    for (let n = 0; n < outLen; n++) {
      curve[n] = out[Math.min(outLen - 1, n + half)];
    }
  }
  return curve;
}

